import pandas as pd

def capitalize_content(user_content: pd.DataFrame) -> pd.DataFrame:
    def convert_word(word: str) -> str:
        if '-' in word:
            return '-'.join(p.capitalize() for p in word.split('-'))
        return word.capitalize()

    def convert_text(text: str) -> str:
        return ' '.join(convert_word(w) for w in text.split(' '))

    df = user_content.copy()
    df['original_text'] = df['content_text']
    df['converted_text'] = df['content_text'].apply(convert_text)
    return df[['content_id', 'original_text', 'converted_text']].sort_values('content_id')
